import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Fonti di una rendita","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nc/ncb.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nc/ncb.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nc/ncb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="fonti-di-una-rendita" tabindex="-1">Fonti di una rendita <a class="header-anchor" href="#fonti-di-una-rendita" aria-label="Permalink to “Fonti di una rendita”">​</a></h1><p>Indichiamo brevemente quali possono essere considerate delle fonti di rendite:</p><ul><li>L&#39;affitto di un appartamento a rata mensile (trimestrale, annuale...) è una rendita a rata mensile (trimestrale, annuale,...).</li><li>L&#39;acquisto a rate di un oggetto qualunque è una rendita le cui rate sono le rate dovute dall&#39;acquirente al venditore.</li><li>Una pensione (o anche stipendio) è matematicamente considerata una rendita le cui rate sono gli importi mensili della pensione stessa.</li><li>Il rimborso periodico di un prestito è una rendita le cui rate sono gli importi periodici dei pagamenti.</li><li>I guadagni che un imprenditore trae annualmente dalla sua attività possono essere considerati rate annuali di una rendita.</li><li>Le spese mensili di gestione (o anche di manutenzione) di un&#39;impresa possono essere considerate rate mensili di una rendita.</li><li>I versamenti periodici, ad esempio mensili, che un risparmiatore fa presso una banca possono essere considerati rate mensili di una rendita.</li></ul><p>Come si vede dagli esempi qui sopra riportati il concetto di rendita è piuttosto ampio ed elastico.</p><p>Nelle pagine successive considereremo particolarmente le rendite a rata costante e vedremo come calcolarne il valore attuale oppure ad una data assegnata.</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};